t_pdf','تصدير العرض','Export quotation','sales'),('quotation_templates.view','عرض القوالب','View quotation templates','sales'),('quotation_templates.manage','إدارة القوالب','Manage quotation templates','sales'),('sales_reports.view','عرض تقارير المبيعات','View sales reports','sales') on conflict(code) do nothing;

-- Read policies expose internal cost/margin only through a restricted view/RPC in integration.
do $$ declare t text; begin foreach t in array array['service_categories','catalog_items','catalog_packages','package_items','sales_sequences','sales_requests','sales_request_attachments','sales_request_status_history','quotation_templates','quotations','quotation_versions','quotation_sections','quotation_line_items','quotation_charges','quotation_terms','approval_policies','approval_steps','approval_requests','approval_decisions','quotation_dispatches','quotation_customer_responses','quotation_status_history'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy sales_requests_read on public.sales_requests for select using(public.is_org_member(organization_id) and public.has_permission(organization_id,'sales_requests.view'));
create policy quotations_read on public.quotations for select using(public.is_org_member(organization_id) and public.has_permission(organization_id,'quotations.view'));
create policy quotation_versions_read on public.quotation_versions for select using(public.is_org_member(organization_id) and public.has_permission(organization_id,'quotations.view'));
create policy catalog_categories_read on public.service_categories for select using(public.is_org_member(organization_id) and public.has_permission(organization_id,'catalog.view'));
create policy catalog_items_read on public.catalog_items for select using(public.is_org_member(organization_id) and public.has_permission(organization_id,'catalog.view'));
create policy catalog_packages_read on public.catalog_packages for select using(public.is_org_member(organization_id) and public.has_permission(organization_id,'catalog.view'));
create policy quotation_templates_read on public.quotation_templates for select using(public.is_org_member(organization_id) and public.has_permission(organization_id,'quotation_templates.view'));
create policy approval_requests_read on public.approval_requests for select using(public.is_org_member(organization_id) and public.has_permission(organization_id,'quotations.view'));
-- No direct INSERT/UPDATE/DELETE policies: sensitive writes must use reviewed security-definer RPCs.

create or replace function public.next_sales_number(target_org uuid,target_type text) returns text language plpgsql security definer set search_path=public as $$ declare y int:=extract(year from now());n bigint;p text;begin if not public.is_org_member(target_org) then raise exception 'Forbidden';end if;if target_type not in('request','quotation') then raise exception 'Invalid sequence type';end if;insert into public.sales_sequences(organization_id,sequence_type,sequence_year,last_value,prefix) values(target_org,target_type,y,1,case when target_type='request' then 'RFQ' else 'QUO' end) on conflict(organization_id,sequence_type,sequence_year) do update set last_value=public.sales_sequences.last_value+1 returning last_value,prefix into n,p;return p||'-'||y||'-'||lpad(n::text,5,'0');end $$;
revoke all on function public.next_sales_number(uuid,text) from public;grant execute on function public.next_sales_number(uuid,text) to authenticated;
-- Future RPC contracts: create_sales_request_from_conversation, create_quotation_version,
-- submit_quotation_for_approval, decide_quotation_approval, dispatch_quotation_demo,
-- and record_quotation_customer_response must lock rows, derive organization membership,
-- verify record_version/idempotency, write history/timeline/audit, and commit atomically.
